      SUBROUTINE ELMODCC     MODIFICATION OF ELEMENTS ON SUBSEQUENT STEPS OF A GIVEN PROBLEM  CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'NDICT.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'VCODE.CIN'C--------------------------------------------------------------      INTEGER         TEXT      EXTERNAL        IDATA, TEXTC--------------------------------------------------------------C      IF (FLUSHL) GO TO 400      IF (LABLE .NE. BLANK) GO TO 100      IF (NTYPE .NE. 0) GO TO 300      GO TO 400C  100 NMATCH = 0      DO 200 NUM = 1, NEL      IF (LABLE .NE. LABEL(NUM)) GO TO 200      NMATCH = NMATCH + 1      I = ISTOR(NUM)      IF (IABS(NTYPE) .NE. IABS(IDATA(I))) THEN        WRITE (NOUT,9271) 9271   FORMAT (' *** MISMATCH OF ELEMENT TYPES ***')        FLUSHL = .TRUE.        GO TO 200      ELSE        DATA(I) = DATUM(1)      ENDIFC      CALL SKETCH(NUM)C      NW = 1C      NDMAX = NDSAV      IF (NTYPE .EQ. 8) NDMAX = 8      IF (NTYPE .EQ. 16) NDMAX = 2      IF (NTYPE .EQ. 38) NDMAX = 20      IF (NTYPE .EQ. 39) NDMAX = NDMAX + 2      DO 110 J = 1, NDMAX      IPTJ = IPTOJ(J)      IF (IPTYP(J) .EQ. 1) THEN        IF (IPTJ .NE. 0) THEN          NW = NW + 1          IADR = I + IPTJ          DATA(IADR) = DATUM(NW)        ELSE           WRITE (NOUT,9272) 9272     FORMAT (' *** ATTEMPT TO CHANGE ORIGINALLY UNSPECIFIED ',     1            'PARAMETER ***')          FLUSHL = .TRUE.        ENDIF      ENDIF  110 CONTINUEC      NP1 = NPARMS + 1      DO 120 J = 2, NP1      IADR = I + J - 1      IF ((TIE(IADR) .NE. 100 .AND. TIE(IADR) .NE. 101     1    .AND. TIE(IADR) .NE. 102) .OR. VCODE(J) .NE. 0)      3    TIE(IADR) = VCODE(J)  120 CONTINUE  200 CONTINUE      IF (NMATCH .GE. 1) GO TO 400C  300 WRITE (NOUT, 9270) LABLE 9270 FORMAT (27H0NO MATCH FOUND FOR LABEL ",A8,1H")      FLUSHL = .TRUE.C  400 CONTINUE      RETURN      END